-- SQL_t05_plans_for_the_owner_reported_four.sql — webdesign.co.uk
--
-- PLANs with criteria fences for the four tools repaired on 2026-07-29 after
-- the owner opened two of them and found both broken. Two of these four could
-- NOT have been caught by the static orphan-reference check at all: their logic
-- lives in external script files the check cannot read. The fences are what let
-- the acceptance ladder hold them to their own claim instead.
--
-- fluid-typography's fence is the interesting one: its tool was never BROKEN,
-- it simply demonstrated nothing where its visitors are. No liveness check can
-- express that. A criteria fence can.

\set ON_ERROR_STOP on

BEGIN;

INSERT INTO doc_plans (subject_type, subject_key, body, source, created_by, is_current)
VALUES ('tool', 'micro-cms', convert_from(decode('','base64'),'UTF8'),
        'webdesign_tools_repair', 'webdesign_couk_thread', true)
ON CONFLICT (subject_type, subject_key) WHERE is_current DO NOTHING;

INSERT INTO doc_notes (subject_type, subject_key, body, categories, source, created_by)
VALUES ('tool', 'micro-cms', convert_from(decode('','base64'),'UTF8'),
        '["repair","tools-programme","owner-reported"]'::jsonb, 'webdesign_tools_repair', 'webdesign_couk_thread');

INSERT INTO doc_plans (subject_type, subject_key, body, source, created_by, is_current)
VALUES ('tool', 'blueprint-compiler', convert_from(decode('','base64'),'UTF8'),
        'webdesign_tools_repair', 'webdesign_couk_thread', true)
ON CONFLICT (subject_type, subject_key) WHERE is_current DO NOTHING;

INSERT INTO doc_notes (subject_type, subject_key, body, categories, source, created_by)
VALUES ('tool', 'blueprint-compiler', convert_from(decode('','base64'),'UTF8'),
        '["repair","tools-programme","owner-reported"]'::jsonb, 'webdesign_tools_repair', 'webdesign_couk_thread');

INSERT INTO doc_plans (subject_type, subject_key, body, source, created_by, is_current)
VALUES ('tool', 'vibe-equalizer', convert_from(decode('','base64'),'UTF8'),
        'webdesign_tools_repair', 'webdesign_couk_thread', true)
ON CONFLICT (subject_type, subject_key) WHERE is_current DO NOTHING;

INSERT INTO doc_notes (subject_type, subject_key, body, categories, source, created_by)
VALUES ('tool', 'vibe-equalizer', convert_from(decode('','base64'),'UTF8'),
        '["repair","tools-programme","owner-reported"]'::jsonb, 'webdesign_tools_repair', 'webdesign_couk_thread');

INSERT INTO doc_plans (subject_type, subject_key, body, source, created_by, is_current)
VALUES ('tool', 'fluid-typography', convert_from(decode('','base64'),'UTF8'),
        'webdesign_tools_repair', 'webdesign_couk_thread', true)
ON CONFLICT (subject_type, subject_key) WHERE is_current DO NOTHING;

INSERT INTO doc_notes (subject_type, subject_key, body, categories, source, created_by)
VALUES ('tool', 'fluid-typography', convert_from(decode('','base64'),'UTF8'),
        '["repair","tools-programme","owner-reported"]'::jsonb, 'webdesign_tools_repair', 'webdesign_couk_thread');

DO $verify$
DECLARE v_missing text;
BEGIN
    SELECT string_agg(k, ', ') INTO v_missing FROM unnest(ARRAY['micro-cms', 'blueprint-compiler', 'vibe-equalizer', 'fluid-typography']) k
     WHERE NOT EXISTS (SELECT 1 FROM doc_plans dp WHERE dp.subject_type='tool'
        AND dp.subject_key=k AND dp.is_current AND dp.body LIKE '%```criteria%');
    IF v_missing IS NOT NULL THEN
        RAISE EXCEPTION 'no current PLAN with a criteria fence for: %', v_missing;
    END IF;
    RAISE NOTICE 'four owner-reported tools now carry PLANs the ladder can test';
END $verify$;

COMMIT;
